43					bounce.rayIndex(),
44					bounce.bounceIndex(),
45					bounce.branchSize(),
46					bounce.shapeMode() ? "SHAPE" : "VOXEL",
47					formatPos(bounce.start()),
48					formatPos(bounce.end()),
49					bounce.materialLabel() == null ? "?" : bounce.materialLabel(),
