560	    /**
561	     * Surveys N/E/D at the same LOD as {@code cellOrigin} for the four-map interaction
562	     * (host→neighbor interaction permeate, {@link FrustumLod#blocksPermeation}; missing neighbors
563	     * count as open). Returns {@code null} when the DDA projection says this exit is a single-axis
564	     * (non-NED) step.
565	     */
566	    private @Nullable ForwardSurvey surveyForward(
567	            BlockPos cellOrigin,
568	            Vec3d cellBase,
569	            int cellSize,
570	            Vec3d hitPos,
571	            Vec3i face,
572	            Vec3d rayDir,
573	            double hostImpedance
574	    ) {
575	        FrustumLod.ForwardMap map = FrustumLod.forwardMap(cellBase, cellSize, hitPos, rayDir, face);
576	        if (map == null) {
577	            return null;
578	        }
579	
580	        Branch nBranch = lodAt(cellOrigin.add(map.nOffset().getX(), map.nOffset().getY(), map.nOffset().getZ()), cellSize);
581	        NeighborSample n = sampleNeighbor(nBranch);
582	        boolean nBlocks = FrustumLod.blocksPermeation(hostImpedance, n.impedance(), n.permeation());
583	
584	        boolean eBlocks = false;
585	        boolean dBlocks = nBlocks;
586	        if (map.hasTangent()) {
587	            Branch eBranch = lodAt(cellOrigin.add(map.eOffset().getX(), map.eOffset().getY(), map.eOffset().getZ()), cellSize);
588	            NeighborSample e = sampleNeighbor(eBranch);
589	            eBlocks = FrustumLod.blocksPermeation(hostImpedance, e.impedance(), e.permeation());
590	
591	            Branch dBranch = lodAt(cellOrigin.add(map.dOffset().getX(), map.dOffset().getY(), map.dOffset().getZ()), cellSize);
592	            NeighborSample d = sampleNeighbor(dBranch);
593	            dBlocks = FrustumLod.blocksPermeation(hostImpedance, d.impedance(), d.permeation());
594	        }
595	
596	        return new ForwardSurvey(FrustumLod.classify(nBlocks, eBlocks, dBlocks));
597	    }
