607	    private static NeighborSample sampleNeighbor(@Nullable Branch b) {
608	        if (b == null) {
609	            return NeighborSample.MISSING;
610	        }
611	        // One descriptor read + one material read, reused for both impedance and permeation —
612	        // two independent Branch.effectiveImpedance()/effectivePermeation() calls would each read
613	        // `material` on their own and could straddle a concurrent rebake.
614	        Branch.NodeDescriptor d = b.descriptor;
615	        Material material = b.material;
616	        double impedance = !Double.isNaN(d.avgImpedance()) ? d.avgImpedance()
617	                : !Double.isNaN(d.mostCommonImpedance()) ? d.mostCommonImpedance()
618	                : material != null ? material.impedance() : Double.NaN;
619	        double permeation = material != null ? material.permeation() : 1.0;
620	        return new NeighborSample(impedance, permeation);
621	    }
