636	    private static double polarizedImpedance(Branch.NodeDescriptor descriptor, Vec3d vector, Vec3d incidentPoint, Vec3d octantCenter, int axisToZero) {
637	        double w = polarBlendWeight(descriptor, vector, incidentPoint, octantCenter, axisToZero);
638	        return Physics.blendImpedance(descriptor.mostCommonImpedance(), descriptor.leastCommonImpedance(), w);
639	    }
