641	    private static double polarBlendWeight(Branch.NodeDescriptor descriptor, Vec3d vector, Vec3d incidentPoint, Vec3d octantCenter, int axisToZero) {
642	        Vec3d pol = descriptor.polar();
643	        if (pol == null || pol.lengthSquared() < 1e-12) {
644	            return 0.5;
645	        }
646	        double blend = descriptor.blendCoefficient();
647	        double s = !Double.isNaN(blend) && blend >= 0.75 ? 2.0 : 1.0;
648	        return Physics.polarBlendWeight(
649	                Physics.dualDerivedAlignment(vector.normalize(), incidentPoint, octantCenter, pol.normalize(), axisToZero), s);
650	    }
