652	    /**
653	     * Axis (0=X, 1=Y, 2=Z; {@code -1} means "zero nothing") to drop from the ray term before
654	     * {@link Physics#dualDerivedNorm} blends it with the position term: whichever axis is neither
655	     * the crossed face's own axis nor the axis of the next face the ray's path projects onto (the
656	     * same DDA pair {@link FrustumLod#forwardMap} computes for quartet/N-E-D neighbor selection).
657	     * Falls back to "zero nothing" when the boundary isn't a genuine two-axis (NED) crossing —
658	     * {@code forwardMap} returns {@code null} for an ordinary single-axis DDA step, and there's no
659	     * well-defined off-plane axis to drop in that case.
660	     */
661	    private static int axisToZeroFor(Vec3d cellBase, int cellSize, Vec3d hitPos, Vec3d rayDir, Vec3i firstPlane) {
662	        FrustumLod.ForwardMap map = FrustumLod.forwardMap(cellBase, cellSize, hitPos, rayDir, firstPlane);
663	        return map == null ? -1 : 3 - map.faceAxis() - map.tangentAxis();
664	    }
