666	    /**
667	     * Reflected ray direction. Polarized octants (a coarse LOD blend, never a genuine 1³ leaf — see
668	     * the assert in {@link #raycast}) use a proper vector-normal mirror off {@code polar} oriented
669	     * to oppose the incoming ray ({@link Physics#opposingPolarNormal}), since the density gradient
670	     * the polarization vector encodes is generally oblique to the cell's own axis-aligned faces.
671	     * Unpolarized boundaries keep the coarse per-axis mirror off the grid face actually crossed.
672	     */
673	    private static Vec3d reflectedDirection(Vec3d vector, Vec3i reflectPlane, @Nullable Vec3d polar) {
674	        if (polar != null && polar.lengthSquared() > 1e-12) {
675	            Vec3d rayNorm = vector.normalize();
676	            Vec3d normal = Physics.opposingPolarNormal(polar.normalize(), rayNorm);
677	            return Physics.pseudoReflect(vector, normal);
678	        }
679	        return Physics.pseudoReflect(vector, reflectPlane);
680	    }
