682	    private static double polarContrast(Branch.NodeDescriptor descriptor) {
683	        double most = descriptor.mostCommonImpedance();
684	        double least = descriptor.leastCommonImpedance();
685	        double denom = Math.max(Math.abs(most), Math.abs(least));
686	        if (denom < 1e-9 || Double.isNaN(denom)) {
687	            return 0.0;
688	        }
689	        return Math.abs(most - least) / denom;
690	    }
