254	    /** Size-1 leaf baked descriptor (frustums-plan.md Phase 0 table): no gradient, max=min=avg. */
255	    private static void bakeLeafDescriptor(Branch leaf) {
256	        double impedance = leaf.material != null ? leaf.material.impedance() : Double.NaN;
