291	    /** Walks real (non-pruned) branches from {@code node} toward {@code pos}, stopping at {@code untilSize}. */
292	    private static Branch descend(Branch node, BlockPos pos, int untilSize) {
293	        Branch current = node;
294	        while (current.size > untilSize && !current.isEmpty()) {
295	            Branch child = current.childAt(pos);
296	            if (child == null) break;
297	            current = child;
298	        }
299	        return current;
